const quizzes = {
  'module-1': {
    title: 'Module 1 Quiz — Security Principles',
    domain: 1,
    questions: [
      { q:'Which element of the CIA triad ensures data is accessible when needed?', opts:['Confidentiality','Integrity','Availability','Non-repudiation'], answer:2, exp:'Availability ensures systems and data are accessible to authorized users when needed.' },
      { q:'A company buys cyber insurance to handle breach costs. Which risk treatment is this?', opts:['Mitigate','Avoid','Transfer','Accept'], answer:2, exp:'Insurance transfers financial risk to the insurance company.' },
      { q:'Which type of control is a security awareness training program?', opts:['Technical','Physical','Administrative','Compensating'], answer:2, exp:'Training is an administrative (people/process) control.' },
      { q:'What is the PRIMARY purpose of hashing?', opts:['Encrypting data','Verifying integrity','Authenticating users','Authorizing access'], answer:1, exp:'Hashing creates a fingerprint to verify data has not been altered.' },
      { q:'Which ISC2 Ethics canon has the HIGHEST priority?', opts:['Provide competent service','Advance the profession','Act honorably','Protect society and the common good'], answer:3, exp:'Canon 1 — Protect society — always takes highest priority.' },
      { q:'An organization accepts a low-probability, low-impact risk without action. This is:', opts:['Mitigate','Avoid','Transfer','Accept'], answer:3, exp:'When risk cost exceeds impact, accepting is appropriate.' },
      { q:'Which concept ensures a person cannot deny having performed an action?', opts:['Confidentiality','Integrity','Authentication','Non-repudiation'], answer:3, exp:'Non-repudiation provides undeniable proof of action via digital signatures or audit logs.' },
      { q:'A firewall is an example of which control type?', opts:['Administrative','Physical','Technical','Compensating'], answer:2, exp:'Firewalls are technology-based — technical controls.' },
      { q:'A vulnerability is a weakness; a threat is:', opts:['Also a weakness','A potential danger that could exploit it','The same as a risk','Always internal'], answer:1, exp:'Threat = potential danger. Vulnerability = weakness. Risk = likelihood × impact.' },
      { q:'Qualitative risk assessment uses:', opts:['Dollar amounts','H/M/L categories','Formulas like ALE','Probability percentages'], answer:1, exp:'Qualitative uses subjective categories. Quantitative uses numbers like ALE.' },
      { q:'Defense in Depth means:', opts:['Strongest single control','Multiple layers of security','Perimeter focus only','User training as primary defense'], answer:1, exp:'Defense in Depth = layered controls so if one fails, others compensate.' },
      { q:'Residual risk is:', opts:['Risk before any controls','Risk remaining after controls','Risk transferred to third party','Risk fully eliminated'], answer:1, exp:'Residual risk = leftover risk after security controls are applied.' },
      { q:'The ISC2 Code of Ethics has how many canons?', opts:['2','3','4','5'], answer:2, exp:'There are 4 canons. Mnemonic: PAPA — Protect, Act, Provide, Advance.' },
      { q:'Which is an example of a physical preventive control?', opts:['CCTV camera','Fire suppression','Security fence','Audit logs'], answer:2, exp:'A fence prevents unauthorized access — physical and preventive.' },
      { q:'ALE is calculated as:', opts:['AV × EF','SLE × ARO','AV ÷ EF','Threat × Vulnerability'], answer:1, exp:'ALE (Annualized Loss Expectancy) = SLE × ARO. SLE = AV × EF.' },
      { q:'The governance document that provides HIGH-LEVEL mandatory direction is a:', opts:['Standard','Guideline','Procedure','Policy'], answer:3, exp:'Policy = high-level mandatory direction. Standards and procedures implement it.' },
      { q:'Data owner is responsible for:', opts:['Day-to-day management of data','Determining data classification and access levels','Using the data','Auditing data usage'], answer:1, exp:'The data owner determines classification, access rights, and data value.' },
      { q:'Which is a detective technical control?', opts:['Firewall','Encryption','IDS/SIEM','Badge reader'], answer:2, exp:'IDS/SIEM detects — it monitors and alerts on suspicious activity.' },
      { q:'Separation of Duties prevents:', opts:['System outages','Fraud by splitting critical tasks','Unauthorized physical access','Malware infections'], answer:1, exp:'SoD ensures no single person controls an entire critical process, preventing fraud.' },
      { q:'Which IS a valid MFA combination?', opts:['Password + security question','PIN + password','Password + fingerprint','Fingerprint + retina scan'], answer:2, exp:'Password (know) + fingerprint (are) = two DIFFERENT factor types = valid MFA.' },
      { q:'An employee is caught reading files outside their job role. Which principle was violated?', opts:['Least privilege','Separation of duties','Defense in depth','Non-repudiation'], answer:0, exp:'Least privilege means access only to what is needed for the job. Reading unrelated files violates this.' },
      { q:'Which is a QUANTITATIVE risk assessment metric?', opts:['High/Medium/Low rating','Color-coded risk matrix','Annualized Loss Expectancy (ALE)','Risk register entries'], answer:2, exp:'ALE is a dollar-based metric — quantitative. H/M/L ratings are qualitative.' },
      { q:'A CCTV camera provides which control function?', opts:['Preventive','Corrective','Detective','Administrative'], answer:2, exp:'CCTV records and monitors — it detects incidents. It can also deter, but its primary function is detective.' },
      { q:'What does EF represent in the SLE formula?', opts:['Expected Failure','Exposure Factor — % of asset lost per incident','Enterprise Function','Error Factor'], answer:1, exp:'EF = Exposure Factor. The percentage of asset value lost in a single incident. SLE = AV × EF.' },
      { q:'Guidelines differ from policies because guidelines are:', opts:['More detailed','Legally binding','Optional best practices','For executives only'], answer:2, exp:'Guidelines are recommended but NOT mandatory. Policies, standards, and procedures ARE mandatory.' },
      { q:'Which attack targets AVAILABILITY?', opts:['Phishing','SQL injection','DDoS','Eavesdropping'], answer:2, exp:'DDoS (Distributed Denial of Service) floods a target with traffic, making it unavailable.' },
      { q:'Tailgating is a threat to which control type?', opts:['Technical','Administrative','Physical','Compensating'], answer:2, exp:'Tailgating (following someone through a secure door) is a physical security threat.' },
      { q:'Which role determines data classification?', opts:['Data custodian','Data user','Data owner','Security officer'], answer:2, exp:'The Data Owner (a senior manager) classifies data and sets access levels. The custodian implements it.' },
      { q:'A penetration test is which type of control?', opts:['Preventive','Detective','Corrective','Deterrent'], answer:1, exp:'Pen tests detect vulnerabilities before attackers do — a proactive detective control.' },
      { q:'Which term describes risk that remains after controls are applied?', opts:['Inherent risk','Transferred risk','Residual risk','Accepted risk'], answer:2, exp:'Residual risk = risk remaining AFTER controls. You can never eliminate all risk.' },
      { q:'Inherent risk is:', opts:['Risk after controls','Risk before any controls','Transferred risk','Accepted risk'], answer:1, exp:'Inherent risk = risk in the absence of any controls. The starting point before mitigation.' },
      { q:'An intruder alarm that sounds when a door is opened is:', opts:['Administrative/Preventive','Physical/Detective','Technical/Corrective','Physical/Deterrent'], answer:1, exp:'An alarm is a physical, detective control — it detects unauthorized access and alerts.' },
      { q:'Which best describes the purpose of a security policy?', opts:['Step-by-step instructions','Specific technical requirements','High-level management direction on security','Optional recommendations'], answer:2, exp:'Policy = high-level mandatory direction. NOT step-by-step (that is procedures) or specific metrics (standards).' },
      { q:'A company stops accepting credit cards online to avoid PCI-DSS requirements. This is risk:', opts:['Transfer','Mitigation','Avoidance','Acceptance'], answer:2, exp:'Eliminating the activity that creates the risk = risk avoidance.' },
      { q:'Which type of analysis uses dollar values to measure risk?', opts:['Qualitative','Quantitative','Subjective','Operational'], answer:1, exp:'Quantitative uses numbers (ALE, SLE, ARO). Qualitative uses H/M/L categories.' },
      { q:'A login banner warning unauthorized users is which control function?', opts:['Preventive','Detective','Corrective','Deterrent'], answer:3, exp:'A warning banner deters attackers — it discourages unauthorized access attempts.' },
      { q:'Which concept ensures information is not disclosed to unauthorized individuals?', opts:['Integrity','Availability','Confidentiality','Authentication'], answer:2, exp:'Confidentiality = protecting information from unauthorized disclosure.' },
      { q:'SLE stands for:', opts:['Single Loss Expectancy','System Loss Evaluation','Security Level Estimate','Standard Loss Equation'], answer:0, exp:'SLE = Single Loss Expectancy = Asset Value × Exposure Factor. Cost of one incident.' },
      { q:'Which security concept requires proof that a sender cannot deny sending a message?', opts:['Authentication','Authorization','Non-repudiation','Confidentiality'], answer:2, exp:'Non-repudiation uses digital signatures to provide undeniable proof of origin.' },
      { q:'Background checks before hiring are which control type?', opts:['Technical preventive','Physical detective','Administrative preventive','Administrative detective'], answer:2, exp:'Background checks are people/process controls (administrative) that prevent hiring threats (preventive).' },
      { q:'A data custodian is responsible for:', opts:['Setting data classification','Day-to-day data management and protection','Defining access policies','Using data for business tasks'], answer:1, exp:'Custodian = IT staff who implement storage, backup, encryption. Owner sets policy; custodian implements.' },
      { q:'Which risk treatment involves purchasing cyber liability insurance?', opts:['Accept','Avoid','Mitigate','Transfer'], answer:3, exp:'Insurance transfers the financial impact of risk to the insurer.' },
      { q:'An organization decides a risk is too low to address. This is:', opts:['Mitigation','Avoidance','Transfer','Acceptance'], answer:3, exp:'When risk impact and likelihood are low, acceptance (doing nothing) may be appropriate.' },
      { q:'Fire suppression systems are which control type?', opts:['Administrative corrective','Physical corrective','Technical preventive','Physical preventive'], answer:1, exp:'Fire suppression = physical (tangible) + corrective (restores/fixes after incident occurs).' },
      { q:'Which principle states that security should not rely on a single control?', opts:['Least privilege','Separation of duties','Defense in depth','Need-to-know'], answer:2, exp:'Defense in depth = multiple layers of security controls working together.' },
      { q:'ARO in risk calculations stands for:', opts:['Annual Risk Output','Annualized Rate of Occurrence','Asset Recovery Objective','Automated Response Operation'], answer:1, exp:'ARO = how often a threat event is expected to occur per year. Used in ALE = SLE × ARO.' },
      { q:'Which governance document provides step-by-step instructions?', opts:['Policy','Standard','Procedure','Guideline'], answer:2, exp:'Procedure = detailed step-by-step instructions for completing a task.' },
      { q:'A standard differs from a guideline because a standard is:', opts:['Optional','High-level direction','Mandatory with specific requirements','A suggestion'], answer:2, exp:'Standards are mandatory and specify measurable requirements. Guidelines are optional recommendations.' },
      { q:'Ransomware violates which CIA properties?', opts:['Confidentiality only','Integrity only','Availability only','Integrity and Availability'], answer:3, exp:'Ransomware encrypts files (modifies = integrity) and prevents access (= availability). Often both.' },
      { q:'An attacker intercepts network traffic without modifying it. Which CIA property is violated?', opts:['Confidentiality','Integrity','Availability','All three'], answer:0, exp:'Passive eavesdropping = unauthorized disclosure = confidentiality violation. No modification (integrity intact).' },
      { q:'Which is the BEST definition of a threat?', opts:['A weakness in a system','A potential danger that could exploit a vulnerability','The probability of an attack','A security control failure'], answer:1, exp:'Threat = potential danger. Vulnerability = weakness. Risk = likelihood × impact of threat exploiting vulnerability.' },
      { q:'Dual control differs from separation of duties because dual control requires:', opts:['Two different job roles','Two people present simultaneously for one action','Splitting tasks across departments','Management approval'], answer:1, exp:'Dual control = two people physically present at same time (e.g., opening a vault). SoD = splitting tasks across people.' },
      { q:'Which ISC2 ethics scenario is correct?', opts:['Report a vulnerability to your employer only','Hide a breach to protect your employer','Report a breach even if your employer objects','Advance your career over public safety'], answer:2, exp:'Canon 1 (protect society) overrides Canon 3 (serve employer). Public safety always wins.' },
      { q:'A visitor badge system is which type of control?', opts:['Technical detective','Administrative preventive','Physical preventive','Physical detective'], answer:2, exp:'Visitor badges are physical (tangible item) and preventive (control who enters secure areas).' },
      { q:'What is the primary goal of a Business Impact Analysis (BIA)?', opts:['Calculate ALE','Identify critical functions and set recovery priorities','Test backup systems','Train employees on security'], answer:1, exp:'BIA identifies which business functions are critical and sets RTO/RPO for each.' },
    ]
  },
  'module-2': {
    title: 'Module 2 Quiz — BC / DR / IR',
    domain: 2,
    questions: [
      { q:'What does RTO measure?', opts:['Maximum acceptable data loss','Maximum acceptable downtime','System uptime percentage','Acceptable risk level'], answer:1, exp:'RTO = Recovery Time Objective = max time a system can be offline.' },
      { q:'During an active incident, what is the FIRST priority after detection?', opts:['Eradication','Recovery','Containment','Lessons learned'], answer:2, exp:'Containment stops the incident from spreading — highest immediate priority.' },
      { q:'Which recovery site is fully equipped and operational within minutes?', opts:['Cold site','Warm site','Hot site','Mobile site'], answer:2, exp:'Hot site = fully equipped, data synced, operational in minutes. Most expensive.' },
      { q:'A BIA is used to:', opts:['Set the IT budget','Identify critical functions and recovery priorities','Replace DRP','Assign blame post-incident'], answer:1, exp:'BIA identifies critical business functions and sets RTO/RPO for each.' },
      { q:'Which backup is FASTEST to perform but SLOWEST to restore?', opts:['Full','Incremental','Differential','Mirror'], answer:1, exp:'Incremental backs up only changes since last backup — fast to create, needs all pieces to restore.' },
      { q:'RPO measures:', opts:['How fast you recover','How much data loss is acceptable','Cost of recovery','Number of redundant systems'], answer:1, exp:'RPO = Recovery Point Objective = maximum acceptable data loss (time).' },
      { q:'The 6 IR phases in correct order are:', opts:['Detect→Prepare→Contain→Eradicate→Recover→Lessons','Prepare→Detect→Contain→Eradicate→Recover→Lessons','Contain→Detect→Prepare→Recover→Eradicate→Lessons','Prepare→Detect→Eradicate→Contain→Recover→Lessons'], answer:1, exp:'Preparation → Detection → Containment → Eradication → Recovery → Lessons Learned.' },
      { q:'A warm site has:', opts:['No equipment','Full equipment and live data','Hardware ready but needs data','Only off-site backups'], answer:2, exp:'Warm site = hardware ready but data needs to be restored. Middle ground between hot and cold.' },
      { q:'Differential backup backs up:', opts:['Everything','Changes since last ANY backup','Changes since last FULL backup','Only new files'], answer:2, exp:'Differential = all changes since the last full backup. Faster restore than incremental.' },
      { q:'Which is NOT an IR phase?', opts:['Preparation','Detection','Negotiation','Recovery'], answer:2, exp:'The 6 phases are Prepare, Detect, Contain, Eradicate, Recover, Lessons. No Negotiation.' },
      { q:'Lessons Learned happens during which IR phase?', opts:['Phase 1','Phase 3','Phase 5','Phase 6'], answer:3, exp:'Lessons Learned is the 6th and final phase — post-incident review to improve future response.' },
      { q:'Which is the CHEAPEST recovery site option?', opts:['Hot site','Warm site','Cold site','Mirror site'], answer:2, exp:'Cold site = empty facility. No equipment, just power and connectivity. Cheapest but slowest to activate.' },
      { q:'MTBF measures:', opts:['Repair time','Average time between failures','Maximum downtime','Backup frequency'], answer:1, exp:'MTBF = Mean Time Between Failures. Higher MTBF = more reliable system.' },
      { q:'MTTR measures:', opts:['Time between incidents','Average time to repair a failed system','Data loss window','Backup window'], answer:1, exp:'MTTR = Mean Time To Repair. Lower MTTR = faster recovery capability.' },
      { q:'A tabletop exercise:', opts:['Tests live systems','Simulates an incident on paper/in discussion','Deploys actual recovery to DR site','Trains users on software'], answer:1, exp:'Tabletop = discussion-based simulation. No live systems affected. Identifies gaps in IR plan.' },
      { q:'Which backup strategy requires the MOST backup sets to restore?', opts:['Full','Differential','Incremental','Mirror'], answer:2, exp:'Incremental restore = last full + EVERY incremental since. Differential = last full + ONE differential.' },
      { q:'BCP is broader than DRP because BCP:', opts:['Costs more','Covers entire business continuity not just IT','Only covers hardware','Is optional'], answer:1, exp:'BCP = entire business. DRP = IT systems only. DRP is a subset of BCP.' },
      { q:'If RPO is 4 hours, an organization can lose at most:', opts:['4 hours of system uptime','4 hours worth of data','4 dollars per incident','4 servers'], answer:1, exp:'RPO defines acceptable data loss measured in time. 4-hour RPO = backups must be at most 4 hours old.' },
      { q:'During containment, an analyst should prioritize:', opts:['Identifying the attacker','Stopping the incident from spreading further','Restoring services','Documenting the full timeline'], answer:1, exp:'Containment = stop the spread immediately. Identification and documentation come later.' },
      { q:'Which disaster recovery test fully activates the DR site?', opts:['Checklist review','Tabletop exercise','Simulation test','Full interruption test'], answer:3, exp:'Full interruption = actual failover to DR site. Most realistic but riskiest and most expensive test.' },
      { q:'Cloud-based disaster recovery is an example of:', opts:['Cold site','Hot site','DRaaS (DR as a Service)','Manual recovery'], answer:2, exp:'DRaaS = Disaster Recovery as a Service. Cloud provider hosts your DR environment.' },
      { q:'Which phase of IR involves patching the vulnerability that was exploited?', opts:['Containment','Eradication','Recovery','Preparation'], answer:1, exp:'Eradication = remove the root cause. Patch the vulnerability, remove malware, close the entry point.' },
      { q:'During recovery, systems should be:', opts:['Restored from any available backup','Verified as clean before returning to production','Put online immediately','Left offline permanently'], answer:1, exp:'Recovery requires verification — ensure systems are clean and functioning before returning to production.' },
      { q:'A Business Continuity Plan (BCP) is triggered by:', opts:['Any IT outage','Only natural disasters','Any event that disrupts critical business functions','Only cyberattacks'], answer:2, exp:'BCP covers ALL disruptions: natural disasters, cyberattacks, power failures, pandemics, etc.' },
      { q:'What is the relationship between RTO and cost?', opts:['Shorter RTO = lower cost','Shorter RTO = higher cost','RTO has no cost impact','Longer RTO = higher cost'], answer:1, exp:'Shorter RTO requires more expensive solutions (hot sites, real-time replication). Cost increases as RTO decreases.' },
      { q:'A pandemic plan is part of:', opts:['DRP only','BCP','Neither','Technical recovery only'], answer:1, exp:'Pandemics affect the entire business (staffing, operations), not just IT. BCP covers all business disruptions.' },
      { q:'Evidence preservation during IR is important for:', opts:['Faster recovery','Legal proceedings and forensics','Reducing downtime','Training new employees'], answer:1, exp:'Proper evidence handling (chain of custody) is critical for legal action and forensic investigation.' },
      { q:'Which backup rotation scheme uses a set of tapes rotated daily/weekly?', opts:['RAID','Grandfather-Father-Son (GFS)','Full mirror','Snapshot'], answer:1, exp:'GFS = Grandfather (monthly full), Father (weekly full), Son (daily incremental). Common rotation scheme.' },
      { q:'After a major incident, the MOST important deliverable from Lessons Learned is:', opts:['Blame assignment','Updated IR plan and procedures','A press release','New hardware purchases'], answer:1, exp:'Lessons Learned = review what worked, what failed, and UPDATE the IR plan to prevent recurrence.' },
      { q:'Maximum Tolerable Downtime (MTD) is:', opts:['Same as RTO','The absolute maximum time a function can be unavailable before permanent damage','Same as RPO','A backup metric'], answer:1, exp:'MTD = the point beyond which the organization suffers irreversible harm. RTO must be shorter than MTD.' },
    ]
  },
  'module-3': {
    title: 'Module 3 Quiz — Access Controls',
    domain: 3,
    questions: [
      { q:'Something you KNOW is which authentication factor?', opts:['Biometric','Possession','Knowledge','Inherence'], answer:2, exp:'Knowledge factor = something you know: passwords, PINs, security questions.' },
      { q:'Password + security question is valid MFA?', opts:['Yes — two factors','No — both are Know factors','Yes — different categories','No — needs 3 factors'], answer:1, exp:'Both password and security question are "something you know" — same category. NOT valid MFA.' },
      { q:'Which access model grants the OWNER control over who accesses their resources?', opts:['MAC','DAC','RBAC','ABAC'], answer:1, exp:'DAC = Discretionary Access Control. The resource owner decides permissions.' },
      { q:'MAC assigns access based on:', opts:['Job role','Owner decision','Clearance labels set by system','Attributes'], answer:2, exp:'MAC = Mandatory Access Control. System enforces access via sensitivity labels. Users cannot override.' },
      { q:'RBAC grants access based on:', opts:['Identity clearance','Resource ownership','Job role','Attributes and context'], answer:2, exp:'RBAC = Role-Based Access Control. Access determined by the user\'s assigned role.' },
      { q:'Least privilege means:', opts:['No access by default','Minimum access needed for the job','Admin access only for seniors','Access based on clearance'], answer:1, exp:'Least privilege = minimum permissions needed to perform the job. Nothing more.' },
      { q:'Zero Trust is based on which principle?', opts:['Trust but verify','Verify once trust forever','Never trust always verify','Trust internal users only'], answer:2, exp:'"Never trust, always verify." Every request is authenticated regardless of source.' },
      { q:'A mantrap (airlock) is which control type?', opts:['Technical','Administrative','Physical','Compensating'], answer:2, exp:'A mantrap is a physical access control — two doors, only one opens at a time.' },
      { q:'When an employee leaves, their access should be:', opts:['Reduced to minimum','Kept active 30 days','Immediately deprovisioned','Transferred to replacement'], answer:2, exp:'Immediate deprovisioning — leaving accounts active is a major security risk.' },
      { q:'PAM focuses on protecting:', opts:['End-user accounts','Admin/privileged accounts','Physical access','Network perimeter'], answer:1, exp:'PAM = Privileged Access Management. Admin accounts are the #1 target for attackers.' },
      { q:'SSO single-point-of-failure means:', opts:['One server hosts everything','One stolen credential = access to everything','One user can log in from one device','SSO is always insecure'], answer:1, exp:'If the SSO credential is compromised, the attacker gains access to ALL connected systems.' },
      { q:'"Login with Google" on Spotify is an example of:', opts:['SSO within one organization','Federation across organizations','DAC','PAM'], answer:1, exp:'Federation = SSO across different organizations. Spotify trusts Google\'s authentication.' },
      { q:'SAML is primarily used for:', opts:['Authorization scopes','Enterprise authentication','IoT device management','Wireless encryption'], answer:1, exp:'SAML (Security Assertion Markup Language) = enterprise SSO/authentication protocol.' },
      { q:'Need-to-Know means:', opts:['Access if you have clearance','Access only what your job requires','Everyone can access public data','Role determines all access'], answer:1, exp:'Even with clearance, access is restricted to only what the job role specifically requires.' },
      { q:'Separation of Duties prevents:', opts:['System outages','Single person controlling entire critical process','Data loss','Malware infections'], answer:1, exp:'SoD splits critical tasks — no single person can commit AND approve a transaction.' },
      { q:'Which is an example of a compensating control?', opts:['Firewall','IDS','Extra logging when MFA cannot be deployed','Security guard'], answer:2, exp:'Compensating controls substitute when the primary control is not feasible. E.g., enhanced monitoring instead of MFA.' },
      { q:'ABAC differs from RBAC because ABAC uses:', opts:['Job roles only','Resource labels only','Multiple attributes: user, resource, environment','Owner discretion'], answer:2, exp:'ABAC = Attribute-Based. Combines user attributes (role), resource attributes (classification), and environment (time, location).' },
      { q:'Dual control requires:', opts:['Two accounts per user','Two administrators to approve critical actions','Two authentication factors','Two firewalls'], answer:1, exp:'Dual control = two authorized people physically present for high-risk actions (vault, nuclear, wire transfers).' },
      { q:'Job rotation helps detect:', opts:['Malware infections','Network intrusions','Fraud by rotating employees through roles','Software bugs'], answer:2, exp:'Job rotation detects fraud — people cannot hide ongoing schemes if someone else takes over their role.' },
      { q:'A smart card is which authentication factor?', opts:['Something you know','Something you have','Something you are','Somewhere you are'], answer:1, exp:'Smart card = physical token = something you HAVE (possession factor).' },
      { q:'Which provides the HIGHEST security for wireless networks?', opts:['WPA2-Personal','WPA3-Personal','WPA2-Enterprise','WPA3-Enterprise'], answer:3, exp:'WPA3-Enterprise uses 256-bit AES + SAE + per-user RADIUS authentication = strongest.' },
      { q:'Kerberos is used for:', opts:['Internet federation','Windows domain SSO via tickets','Web OAuth flows','Wireless encryption'], answer:1, exp:'Kerberos = ticket-based authentication for Windows Active Directory environments. Internal SSO.' },
      { q:'OAuth 2.0 is primarily an:', opts:['Authentication protocol','Authorization protocol','Encryption scheme','Hashing algorithm'], answer:1, exp:'OAuth 2.0 = authorization (what can the app ACCESS?). OpenID Connect adds authentication on top.' },
      { q:'Which physical control prevents vehicular ramming attacks?', opts:['CCTV','Security guard','Bollards','Mantrap'], answer:2, exp:'Bollards = concrete/steel posts that physically block vehicles from ramming building entrances.' },
      { q:'Which access control model is MOST commonly used in corporate environments?', opts:['DAC','MAC','RBAC','Rule-based'], answer:2, exp:'RBAC is the most common enterprise model — roles map to job functions, simplifying administration.' },
      { q:'Biometric FALSE acceptance rate (FAR) means:', opts:['Legitimate user is rejected','Unauthorized user is accepted','System crashes','Biometric data is lost'], answer:1, exp:'FAR = unauthorized person incorrectly accepted. FRR = authorized person incorrectly rejected.' },
      { q:'Crossover Error Rate (CER) in biometrics is:', opts:['Maximum error rate','Point where FAR equals FRR','Minimum error rate','Hardware failure rate'], answer:1, exp:'CER (also called Equal Error Rate) = where FAR and FRR intersect. Lower CER = more accurate system.' },
      { q:'Account lockout after failed login attempts is:', opts:['Detective control','Preventive control','Corrective control','Compensating control'], answer:1, exp:'Account lockout prevents brute force attacks by blocking further login attempts — preventive.' },
      { q:'Privilege escalation means:', opts:['User loses access','User gains higher privileges than authorized','Admin resets a password','User changes their role'], answer:1, exp:'Privilege escalation = attacker gains admin/root access from a lower-privileged account. Major threat.' },
      { q:'Context-based authentication considers:', opts:['Only username and password','Location, time, device, and behavior','Only biometrics','Only security questions'], answer:1, exp:'Context-based auth evaluates environmental attributes: where, when, what device, normal behavior pattern.' },
      { q:'LDAP is used for:', opts:['Encrypting files','Directory services and authentication lookups','Firewall rules','Network routing'], answer:1, exp:'LDAP = Lightweight Directory Access Protocol. Used to query directory services like Active Directory.' },
      { q:'Privilege creep occurs when:', opts:['Users accumulate permissions from past roles without removal','Admins lose access','Passwords expire','Systems are patched'], answer:0, exp:'Privilege creep = users collect permissions as they change roles but old permissions are never revoked.' },
      { q:'Access review (recertification) should be performed:', opts:['Only during onboarding','Only during termination','Periodically (quarterly/annually)','Never — set it and forget it'], answer:2, exp:'Regular access reviews ensure users only retain permissions they currently need. Catches privilege creep.' },
      { q:'Type 1 authentication error is:', opts:['False acceptance','False rejection (legitimate user denied)','System error','Network timeout'], answer:1, exp:'Type 1 = False Rejection Rate (FRR). Legitimate user denied. Type 2 = False Acceptance Rate (FAR).' },
      { q:'Rule-based access control makes decisions using:', opts:['User roles','Owner discretion','IF-THEN rules and conditions','Sensitivity labels'], answer:2, exp:'Rule-based = predefined rules (e.g., IF time is after 6pm THEN deny access). Often used in firewalls.' },
      { q:'Federated identity management requires:', opts:['All users in one directory','Trust relationships between identity providers','Physical tokens for everyone','No passwords'], answer:1, exp:'Federation = organizations establish trust so users authenticated by one IdP are accepted by partner SPs.' },
      { q:'Session management is important because:', opts:['It speeds up authentication','Stolen session tokens can bypass authentication entirely','It reduces password complexity','It enables SSO'], answer:1, exp:'If an attacker steals a session token/cookie, they can impersonate the user without credentials.' },
      { q:'Default deny (implicit deny) means:', opts:['All access is granted by default','Access is denied unless explicitly permitted','Only admins are denied','Passwords are not required'], answer:1, exp:'Default deny = everything is blocked unless a specific rule allows it. Fundamental security principle.' },
      { q:'Which is an example of Type 2 authentication error?', opts:['Authorized user denied access','Unauthorized user granted access','System reboot','Password expired'], answer:1, exp:'Type 2 = False Acceptance (FAR). An impostor is incorrectly accepted by the system.' },
      { q:'Just-in-Time (JIT) provisioning means:', opts:['Creating accounts months in advance','Creating/granting access only when needed, revoking after','Permanent admin access','Shared admin accounts'], answer:1, exp:'JIT = temporary, time-limited access. Admin rights granted only for the task duration, then auto-revoked.' },
    ]
  },
  'module-4': {
    title: 'Module 4 Quiz — Network Security',
    domain: 4,
    questions: [
      { q:'Which OSI layer routes data using IP addresses?', opts:['Layer 1 Physical','Layer 2 Data Link','Layer 3 Network','Layer 4 Transport'], answer:2, exp:'Layer 3 (Network) handles IP addressing and routing between networks.' },
      { q:'Default port for HTTPS?', opts:['80','443','22','8080'], answer:1, exp:'HTTPS = port 443. HTTP = port 80. SSH = port 22.' },
      { q:'TCP vs UDP: what is the key difference?', opts:['TCP is faster','TCP guarantees delivery; UDP does not','UDP uses encryption','They are the same'], answer:1, exp:'TCP is reliable (guaranteed delivery, ordered, error-correcting). UDP is fast but fire-and-forget.' },
      { q:'A DMZ is:', opts:['An encryption algorithm','Network segment between internet and internal network','A type of firewall','A backup location'], answer:1, exp:'DMZ = Demilitarized Zone. Buffer network between untrusted internet and trusted internal network.' },
      { q:'Which device actively BLOCKS malicious traffic?', opts:['IDS','IPS','Router','Hub'], answer:1, exp:'IPS is inline and blocks. IDS is passive — detects and alerts only.' },
      { q:'Strongest wireless encryption standard?', opts:['WEP','WPA','WPA2','WPA3'], answer:3, exp:'WPA3 is the latest and strongest. WEP is completely broken. WPA/WPA2 have vulnerabilities.' },
      { q:'Port 22 is used by:', opts:['HTTP','Telnet','SSH','FTP'], answer:2, exp:'SSH (Secure Shell) uses port 22. It is the secure replacement for Telnet (port 23).' },
      { q:'A stateful firewall differs because it:', opts:['Only inspects IPs','Tracks active connection state','Works only on wireless','Cannot block traffic'], answer:1, exp:'Stateful firewalls track the state of connections — aware of the full TCP conversation.' },
      { q:'DDoS attacks:', opts:['Steal credentials','Intercept traffic','Flood targets to deny access','Inject SQL commands'], answer:2, exp:'DDoS = Distributed Denial of Service. Floods target with traffic to make it unavailable.' },
      { q:'In cloud shared responsibility, who secures data IN the cloud?', opts:['Cloud provider only','The customer','ISP','The government'], answer:1, exp:'Shared Responsibility: provider secures the cloud infrastructure; customer secures their data and apps.' },
      { q:'ARP poisoning enables which attack?', opts:['SQL Injection','Man-in-the-Middle','DDoS','Ransomware'], answer:1, exp:'ARP poisoning tricks devices into sending traffic to the attacker — enabling MITM.' },
      { q:'MAC flooding causes a switch to:', opts:['Crash and reboot','Act like a hub (broadcast all traffic)','Block all traffic','Enable VLANs'], answer:1, exp:'MAC table overflow causes the switch to broadcast to all ports — like a hub — allowing sniffing.' },
      { q:'VLAN hopping is a security attack targeting:', opts:['Layer 1','Layer 2','Layer 3','Layer 7'], answer:1, exp:'VLAN hopping is a Layer 2 attack — attacker crosses VLAN boundaries they should not access.' },
      { q:'TCP 3-way handshake: correct sequence?', opts:['ACK→SYN→SYN-ACK','SYN→SYN-ACK→ACK','SYN-ACK→SYN→ACK','SYN→ACK→SYN-ACK'], answer:1, exp:'SYN → SYN-ACK → ACK. Like a phone call: dial, answer, confirm.' },
      { q:'Which protocol replaced Telnet for secure remote access?', opts:['FTP','HTTP','SSH','SMTP'], answer:2, exp:'SSH (port 22) replaced Telnet (port 23). Same function — SSH encrypts everything.' },
      { q:'Which OSI layer handles data formatting, encryption, and compression?', opts:['Application (7)','Presentation (6)','Session (5)','Transport (4)'], answer:1, exp:'Layer 6 (Presentation) handles data format translation, encryption (SSL/TLS), and compression.' },
      { q:'NAC (Network Access Control) checks:', opts:['Only passwords','Device health and compliance before granting network access','Only IP addresses','Only MAC addresses'], answer:1, exp:'NAC verifies devices meet security requirements (patched, AV updated, compliant) before network access.' },
      { q:'A proxy firewall operates at which OSI layer?', opts:['Layer 2','Layer 3','Layer 4','Layer 7'], answer:3, exp:'Proxy/application firewalls inspect full application content at Layer 7 — understands HTTP, FTP, etc.' },
      { q:'DNS over HTTPS (DoH) provides:', opts:['Faster DNS','Encrypted DNS queries preventing eavesdropping','Larger DNS records','Redundant DNS'], answer:1, exp:'DoH encrypts DNS queries inside HTTPS, preventing ISPs and attackers from seeing what domains you visit.' },
      { q:'Port 3389 is used by:', opts:['SSH','HTTP','RDP (Remote Desktop)','SMTP'], answer:2, exp:'RDP = port 3389. High-value attack target — always protect with VPN + MFA.' },
      { q:'A honeypot is:', opts:['A type of firewall','A decoy system designed to attract attackers','An encryption algorithm','A backup server'], answer:1, exp:'Honeypot = fake system that appears valuable. Attracts attackers, allowing you to study their methods.' },
      { q:'Which protocol provides secure email transmission?', opts:['SMTP on port 25','SMTP with STARTTLS on port 587','POP3 on port 110','HTTP on port 80'], answer:1, exp:'SMTP port 587 with STARTTLS encrypts email in transit. Port 25 SMTP is unencrypted.' },
      { q:'Subnet masks are used to:', opts:['Encrypt traffic','Divide networks into smaller segments','Replace firewalls','Speed up DNS'], answer:1, exp:'Subnetting divides a large network into smaller, more manageable and secure segments.' },
      { q:'IPv6 addresses are:', opts:['32-bit','64-bit','128-bit','256-bit'], answer:2, exp:'IPv6 = 128-bit addresses (vs IPv4 32-bit). Provides vastly more addresses and built-in IPSec support.' },
      { q:'A WAF (Web Application Firewall) protects against:', opts:['Physical attacks','Layer 7 attacks like SQL injection and XSS','Layer 1 cable tapping','Layer 2 ARP poisoning'], answer:1, exp:'WAF specifically protects web applications from Layer 7 attacks: SQLi, XSS, CSRF, etc.' },
      { q:'DHCP snooping prevents:', opts:['DNS attacks','Rogue DHCP servers assigning fake IP configurations','ARP attacks','SYN floods'], answer:1, exp:'DHCP snooping validates DHCP messages and blocks unauthorized DHCP servers on the network.' },
      { q:'The purpose of a reverse proxy is to:', opts:['Speed up client browsing','Protect backend servers by handling external requests','Replace DNS','Monitor internal traffic'], answer:1, exp:'Reverse proxy sits in front of servers, hiding their identity and providing load balancing and security.' },
      { q:'Which cloud deployment model combines public and private clouds?', opts:['Public','Private','Hybrid','Community'], answer:2, exp:'Hybrid cloud = mix of public and private clouds. Sensitive data stays private; scalable workloads go public.' },
      { q:'SaaS security responsibility for the customer includes:', opts:['Hardware maintenance','OS patching','Data and user access management','Network infrastructure'], answer:2, exp:'In SaaS, the customer is responsible for their data, user access, and configuration. Provider handles everything else.' },
      { q:'Zero-day vulnerabilities are dangerous because:', opts:['They are old and well-known','No patch exists yet — signature-based detection fails','They only affect physical security','They are easy to fix'], answer:1, exp:'Zero-day = unknown vulnerability with no patch. Signature-based IDS/IPS cannot detect it.' },
      { q:'Port scanning is used to:', opts:['Encrypt traffic','Discover open ports and services on a target','Block malware','Manage VLANs'], answer:1, exp:'Port scanning (e.g., Nmap) identifies open ports and running services — used in both recon and security auditing.' },
      { q:'A smurf attack is a type of:', opts:['SQL injection','DDoS using ICMP broadcast','Phishing','Password cracking'], answer:1, exp:'Smurf attack = attacker sends ICMP ping to broadcast address with spoofed source IP. All hosts reply to victim = DDoS.' },
      { q:'802.11 refers to:', opts:['Ethernet wired standard','Wi-Fi wireless standards','Bluetooth','Cellular networks'], answer:1, exp:'IEEE 802.11 = wireless LAN (Wi-Fi) standards. 802.11ac, 802.11ax (Wi-Fi 6), etc.' },
      { q:'Network segmentation reduces risk by:', opts:['Encrypting all traffic','Limiting lateral movement if one segment is compromised','Removing all firewalls','Increasing bandwidth'], answer:1, exp:'Segmentation isolates network zones — if one segment is breached, the attacker cannot freely move to others.' },
      { q:'POP3 vs IMAP: IMAP:', opts:['Downloads and deletes email from server','Syncs email — keeps it on server','Sends email','Encrypts email'], answer:1, exp:'IMAP syncs (email stays on server, accessible from multiple devices). POP3 downloads and removes from server.' },
      { q:'A ping sweep is used to:', opts:['Test DNS','Discover live hosts on a network','Encrypt traffic','Block ports'], answer:1, exp:'Ping sweep sends ICMP echo requests to a range of IPs to identify which hosts are alive.' },
      { q:'Spanning Tree Protocol (STP) prevents:', opts:['ARP poisoning','Switching loops in Layer 2 networks','IP spoofing','DNS hijacking'], answer:1, exp:'STP prevents broadcast storms caused by redundant switch paths creating loops at Layer 2.' },
      { q:'IaaS gives the customer control over:', opts:['Nothing — provider manages all','OS, applications, and data','Only data','Only user accounts'], answer:1, exp:'IaaS = customer manages OS, middleware, runtime, apps, and data. Provider manages hardware and network.' },
      { q:'TLS operates at which OSI layer?', opts:['Layer 2','Layer 4','Layer 6 (Presentation)','Layer 7'], answer:2, exp:'TLS operates at the Presentation layer (Layer 6) — handles encryption/decryption of data for applications.' },
      { q:'Which protocol replaced SSL?', opts:['SSH','TLS','IPSec','AES'], answer:1, exp:'TLS (Transport Layer Security) replaced SSL (Secure Sockets Layer). SSL is deprecated and insecure.' },
    ]
  },
  'module-5': {
    title: 'Module 5 Quiz — Security Operations',
    domain: 5,
    questions: [
      { q:'Primary purpose of a SIEM?', opts:['Encrypt all data','Centralized log collection, correlation, and alerting','Manage passwords','Perform penetration tests'], answer:1, exp:'SIEM = Security Information and Event Management. Aggregates logs, correlates events, generates alerts.' },
      { q:'AES is which type of encryption?', opts:['Asymmetric','Symmetric','Hashing','Steganography'], answer:1, exp:'AES = symmetric encryption (one shared key). RSA = asymmetric (public/private key pair).' },
      { q:'Which hash algorithm is BROKEN and should NOT be used?', opts:['SHA-256','SHA-512','MD5','AES'], answer:2, exp:'MD5 has known collision vulnerabilities. SHA-256 is the current standard.' },
      { q:'Egress monitoring watches:', opts:['Traffic entering the network','Traffic leaving the network','Physical access','Training completion'], answer:1, exp:'Egress = outbound. Monitors for data exfiltration — data leaving without authorization.' },
      { q:'Crypto shredding works by:', opts:['Physical shredding','Overwriting with random data','Destroying the encryption key','Using a strong magnet'], answer:2, exp:'Crypto shredding destroys the encryption key — the data remains but is permanently unreadable.' },
      { q:'Digital signatures provide:', opts:['Confidentiality only','Integrity only','Integrity + Authentication + Non-repudiation','Speed and compression'], answer:2, exp:'Digital signatures provide three: data integrity, sender authentication, and non-repudiation.' },
      { q:'System hardening means:', opts:['Adding RAM','Removing unnecessary services and securing configs','Adding more firewalls','Making hardware physically stronger'], answer:1, exp:'Hardening = reduce attack surface by removing unneeded services, closing ports, securing settings.' },
      { q:'Security awareness training primarily addresses:', opts:['Software bugs','Hardware failures','Human error and social engineering','Network bandwidth'], answer:2, exp:'Training targets the human element — the most exploited attack vector in cybersecurity.' },
      { q:'Patch management is:', opts:['System hardening','Configuration management','Applying fixes for known vulnerabilities','Change management'], answer:2, exp:'Patch management = applying software updates to close known vulnerabilities.' },
      { q:'Data at rest encryption protects data:', opts:['While being transmitted','While being processed','Stored on disk or storage media','During backup'], answer:2, exp:'Data at rest = stored data (hard drives, databases, backups). Encryption prevents unauthorized access if media is stolen.' },
      { q:'DLP (Data Loss Prevention) monitors:', opts:['Physical access','Data movement to prevent unauthorized exfiltration','Network bandwidth','User training completion'], answer:1, exp:'DLP watches for sensitive data leaving the organization via email, USB, cloud upload, etc.' },
      { q:'Which is the recommended algorithm for password hashing?', opts:['MD5','SHA-1','bcrypt','AES'], answer:2, exp:'bcrypt is designed for password hashing — includes automatic salting and adjustable cost factor.' },
      { q:'A salt in password hashing:', opts:['Encrypts the password','Adds random data before hashing to prevent rainbow table attacks','Compresses the password','Replaces the password'], answer:1, exp:'Salt = random value added to each password before hashing. Same password + different salt = different hash.' },
      { q:'Change management ensures:', opts:['All changes are blocked','Changes are reviewed, approved, tested, and documented','Only admins can make changes','Systems never change'], answer:1, exp:'Change management = formal process to evaluate, approve, test, and document system changes to prevent disruptions.' },
      { q:'Vulnerability scanning differs from penetration testing because scanning:', opts:['Exploits vulnerabilities','Only identifies vulnerabilities without exploiting','Is illegal','Requires physical access'], answer:1, exp:'Scanning = automated identification. Pen testing = manual exploitation to prove impact. Scanning finds; pen testing proves.' },
      { q:'Configuration management ensures:', opts:['All systems use the same password','Systems maintain approved, documented configurations','No changes are ever made','Only new systems are configured'], answer:1, exp:'Config management = maintain consistent, documented, approved system settings. Detect unauthorized changes.' },
      { q:'Steganography is:', opts:['A type of encryption','Hiding data within other data (e.g., image files)','A hashing algorithm','A firewall type'], answer:1, exp:'Steganography hides secret data inside innocent-looking files (images, audio). The hidden data is invisible.' },
      { q:'The principle of data minimization means:', opts:['Collect all possible data','Collect and retain only the minimum data necessary','Never delete data','Encrypt all data'], answer:1, exp:'Data minimization (GDPR principle) = only collect what you need, only keep it as long as needed.' },
      { q:'Degaussing destroys data by:', opts:['Overwriting with zeros','Applying a powerful magnetic field','Physical shredding','Encrypting and deleting the key'], answer:1, exp:'Degaussing = strong magnetic field that destroys data on magnetic media (HDD, tape). Does NOT work on SSDs.' },
      { q:'A security baseline is:', opts:['The maximum security level','Minimum security configuration standard for systems','Optional best practice','A type of firewall rule'], answer:1, exp:'Baseline = minimum required security configuration. All systems must meet or exceed the baseline.' },
      { q:'SOC (Security Operations Center) primary function:', opts:['Develop software','Monitor, detect, and respond to security incidents 24/7','Manage HR','Handle finances'], answer:1, exp:'SOC = dedicated team that monitors security events, investigates alerts, and responds to incidents around the clock.' },
      { q:'Separation of environments (dev/test/prod) prevents:', opts:['All security incidents','Untested changes from affecting production systems','Hardware failures','Data backup issues'], answer:1, exp:'Separate environments ensure changes are tested in dev/staging before reaching production — reducing risk of outages.' },
      { q:'Which encryption mode is used for full disk encryption?', opts:['ECB','CBC','XTS-AES','RSA'], answer:2, exp:'XTS-AES is the standard mode for full disk encryption (BitLocker, FileVault). Designed for storage encryption.' },
      { q:'Certificate pinning prevents:', opts:['Physical theft','MITM attacks using fraudulent certificates','DDoS attacks','SQL injection'], answer:1, exp:'Certificate pinning = app only trusts specific certificates, not any CA-signed cert. Prevents MITM with fake certs.' },
      { q:'Forward secrecy ensures:', opts:['Future messages are encrypted','Past sessions cannot be decrypted even if long-term keys are compromised','Keys never expire','Encryption is faster'], answer:1, exp:'Forward secrecy = unique session keys. Compromising the server\'s private key does not decrypt past recorded traffic.' },
      { q:'Log retention policies define:', opts:['Who can read logs','How long logs must be stored before deletion','Log file format','Which systems generate logs'], answer:1, exp:'Retention policies specify minimum/maximum storage duration for logs — balancing compliance, forensics, and storage costs.' },
      { q:'Threat intelligence feeds provide:', opts:['Encryption keys','Real-time data about emerging threats, IOCs, and attack patterns','Physical security alerts','Training materials'], answer:1, exp:'Threat intel = actionable data about current threats (malicious IPs, domains, file hashes) to proactively defend.' },
      { q:'The shared responsibility model in cloud means:', opts:['Provider is responsible for everything','Customer is responsible for everything','Security is shared between provider and customer','No one is responsible'], answer:2, exp:'Provider secures the cloud infrastructure. Customer secures their data, access, and applications within the cloud.' },
      { q:'Tokenization replaces sensitive data with:', opts:['Encrypted ciphertext','Non-sensitive placeholder tokens','Hashed values','Compressed data'], answer:1, exp:'Tokenization substitutes sensitive data (credit card numbers) with random tokens. Original data stored in secure vault.' },
      { q:'An IOC (Indicator of Compromise) is:', opts:['A security policy','Evidence that a security breach may have occurred','A type of firewall','An encryption standard'], answer:1, exp:'IOC = artifact observed on a system/network indicating potential compromise: unusual IPs, file hashes, registry changes.' },
      { q:'Asymmetric encryption uses:', opts:['One shared key','Two keys: public and private','No keys','Three keys'], answer:1, exp:'Asymmetric = key pair. Public key encrypts (shared freely). Private key decrypts (kept secret). RSA, ECC.' },
      { q:'Which is NOT a valid data state?', opts:['Data at rest','Data in transit','Data in use','Data in archive'], answer:3, exp:'The three data states are: at rest (stored), in transit (moving), in use (processing). "In archive" is a subset of at rest.' },
      { q:'Obfuscation in security means:', opts:['Making data clearer','Making code or data harder to understand to deter reverse engineering','Encrypting with AES','Hashing passwords'], answer:1, exp:'Obfuscation = deliberately making code/data difficult to interpret. Deters analysis but is NOT encryption.' },
      { q:'A code signing certificate verifies:', opts:['Website identity','That software has not been tampered with and its publisher identity','Email encryption','VPN connections'], answer:1, exp:'Code signing = developer signs software with their certificate. Users verify the code is authentic and unmodified.' },
      { q:'Ephemeral keys are:', opts:['Permanent encryption keys','Temporary keys used once then discarded','Backup keys','Master keys'], answer:1, exp:'Ephemeral = temporary session keys. Used once, never stored. Enables forward secrecy in TLS 1.3.' },
    ]
  },
  'practice-exam': {
    title: 'Full Practice Exam — 50 Questions',
    domain: 0,
    questions: [
      { q:'Which CIA element ensures data is accessible to authorized users?', opts:['Confidentiality','Integrity','Availability','Non-repudiation'], answer:2, exp:'Availability = systems accessible when authorized users need them.' },
      { q:'Buying cyber insurance is which risk treatment?', opts:['Mitigate','Avoid','Transfer','Accept'], answer:2, exp:'Insurance transfers financial risk to the insurance company.' },
      { q:'Security awareness training is which control type?', opts:['Technical','Physical','Administrative','Corrective'], answer:2, exp:'Training is an administrative control.' },
      { q:'PRIMARY purpose of hashing?', opts:['Encrypt data','Verify integrity','Authenticate users','Authorize access'], answer:1, exp:'Hashing verifies data has not been altered.' },
      { q:'Highest priority ISC2 Ethics canon?', opts:['Provide competent service','Advance the profession','Act honorably','Protect society'], answer:3, exp:'Canon 1 (Protect society) always takes priority.' },
      { q:'ALE is calculated as:', opts:['AV × EF','SLE × ARO','AV ÷ ARO','Threat × Impact'], answer:1, exp:'ALE = SLE × ARO. SLE = Asset Value × Exposure Factor.' },
      { q:'A fence is which type and function of control?', opts:['Administrative/Preventive','Physical/Preventive','Technical/Detective','Physical/Corrective'], answer:1, exp:'A fence is a Physical control that Prevents unauthorized physical access.' },
      { q:'Defense in Depth means:', opts:['Strongest single control','Multiple security layers','Perimeter defense only','Training as primary defense'], answer:1, exp:'Multiple layers so if one fails, others compensate.' },
      { q:'Non-repudiation ensures:', opts:['Data confidentiality','Data integrity','Person cannot deny their action','System availability'], answer:2, exp:'Non-repudiation = undeniable proof of action (digital signatures, audit logs).' },
      { q:'Qualitative risk uses:', opts:['Dollar amounts','H/M/L categories','ALE formulas','Probability math'], answer:1, exp:'Qualitative = subjective categories. Quantitative = dollar-based numbers.' },
      { q:'RTO measures:', opts:['Max data loss','Max acceptable downtime','System uptime %','Backup frequency'], answer:1, exp:'RTO = Recovery Time Objective = maximum time a system can be offline.' },
      { q:'Hot site is:', opts:['Cheapest recovery option','Fully equipped, operational in minutes','Hardware ready, needs data','Empty facility'], answer:1, exp:'Hot site = most expensive, fully ready, minimal switchover time.' },
      { q:'IR containment is the priority because:', opts:['It erases evidence','It stops the incident spreading','It identifies the attacker','It restores services'], answer:1, exp:'Containment prevents the incident from affecting more systems.' },
      { q:'Incremental backup:', opts:['Backs up everything','Backs up changes since last full','Backs up changes since last ANY backup','Mirrors all data'], answer:2, exp:'Incremental = changes since last backup (full OR incremental). Fastest to create, slowest to restore.' },
      { q:'Something you HAVE factor example:', opts:['Password','Fingerprint','Security token/phone','PIN'], answer:2, exp:'Something you have = possession factor: token, smart card, phone app.' },
      { q:'Valid MFA combination:', opts:['Password + PIN','Password + security question','Password + fingerprint','Fingerprint + retina scan'], answer:2, exp:'Password (know) + fingerprint (are) = different categories = valid MFA.' },
      { q:'DAC access control: who decides permissions?', opts:['The system based on labels','The job role','The resource owner','The security officer'], answer:2, exp:'DAC = resource owner decides who gets access.' },
      { q:'MAC is most secure because:', opts:['Users can configure it','Owners control access','Centrally enforced system labels, users cannot override','It uses encryption'], answer:2, exp:'MAC = Mandatory. System enforces based on labels. No user discretion allowed.' },
      { q:'Least privilege principle:', opts:['Minimum access for the job','No access by default','Admin access only','Clearance-based access'], answer:0, exp:'Least privilege = minimum permissions needed to do the job. Nothing extra.' },
      { q:'Zero Trust: what does it assume?', opts:['Internal network is safe','Once authenticated, trust continues','Network is always compromised, verify everything','Only verify external users'], answer:2, exp:'"Never trust, always verify." Assume breach. Verify every request regardless of origin.' },
      { q:'PAM protects:', opts:['End-user accounts','Admin/privileged accounts','Physical access points','Network segmentation'], answer:1, exp:'PAM = Privileged Access Management. Admins have the most powerful — and dangerous — accounts.' },
      { q:'SSO primary risk:', opts:['Too many passwords','Single point of failure — one cred compromises everything','Poor user experience','High cost'], answer:1, exp:'SSO convenience = single point of failure risk. Must pair with strong MFA.' },
      { q:'"Login with Google" on a third-party app is:', opts:['DAC','SSO within one org','Federation across orgs','RBAC'], answer:2, exp:'Federation = SSO crossing organizational boundaries. Google authenticates; third party trusts.' },
      { q:'OSI Layer 3 routes using:', opts:['MAC addresses','IP addresses','Port numbers','Frame checksums'], answer:1, exp:'Layer 3 = Network. Uses IP addresses for routing between networks.' },
      { q:'HTTPS default port:', opts:['80','22','443','3389'], answer:2, exp:'HTTPS = port 443. HTTP = port 80. Remember: S adds security and 363 to the port.' },
      { q:'TCP vs UDP: TCP guarantees:', opts:['Speed','Delivery order and reliability','Connectionless transmission','Low overhead'], answer:1, exp:'TCP = reliable, ordered, acknowledged delivery. UDP = fast, connectionless, no guarantee.' },
      { q:'DMZ purpose:', opts:['Encrypt traffic','Buffer zone between internet and internal network','Replace firewalls','Store backups'], answer:1, exp:'DMZ = Demilitarized Zone. Hosts public-facing services while protecting internal network.' },
      { q:'IPS vs IDS: IPS:', opts:['Only detects','Only alerts','Actively blocks malicious traffic','Logs everything passively'], answer:2, exp:'IPS is inline and blocks. IDS is passive (detect + alert only). IPS = guard; IDS = camera.' },
      { q:'Strongest wireless encryption:', opts:['WEP','WPA','WPA2','WPA3'], answer:3, exp:'WPA3 = strongest current standard. WEP is completely broken. Never use WEP.' },
      { q:'SSH port:', opts:['21','22','23','25'], answer:1, exp:'SSH = 22. Telnet = 23. FTP = 21. SSH is the secure replacement for Telnet.' },
      { q:'Stateful firewall tracks:', opts:['Only IP addresses','Connection state and session context','Application layer content','Only port numbers'], answer:1, exp:'Stateful = aware of TCP session state (handshake, established, teardown). Smarter than packet-filtering.' },
      { q:'ARP poisoning enables:', opts:['DDoS','SQL Injection','Man-in-the-Middle','Ransomware'], answer:2, exp:'ARP poisoning tricks devices into sending traffic to attacker = MITM attack.' },
      { q:'TCP handshake sequence:', opts:['ACK→SYN→SYN-ACK','SYN→SYN-ACK→ACK','SYN-ACK→SYN→ACK','SYN→ACK→FIN'], answer:1, exp:'SYN → SYN-ACK → ACK. Three-way. Like a phone call: dial, pick up, confirm.' },
      { q:'VLAN primary security benefit:', opts:['Faster speeds','Network isolation — limits broadcast domains and attack spread','Removes need for firewalls','Enables wireless access'], answer:1, exp:'VLANs create logical isolation on the same physical switch, limiting attack lateral movement.' },
      { q:'SIEM primary function:', opts:['Encrypt data','Block attacks','Collect, correlate and alert on log data','Manage user identities'], answer:2, exp:'SIEM aggregates logs from across the environment, correlates events, and triggers alerts.' },
      { q:'AES is:', opts:['Asymmetric encryption','Hashing algorithm','Symmetric encryption','Digital signature scheme'], answer:2, exp:'AES = Advanced Encryption Standard = symmetric (one shared key).' },
      { q:'MD5 is:', opts:['Current hashing standard','Broken and should not be used','Symmetric encryption','Asymmetric protocol'], answer:1, exp:'MD5 has known collision vulnerabilities. Use SHA-256 instead.' },
      { q:'Digital signatures provide:', opts:['Confidentiality','Integrity + Authentication + Non-repudiation','Speed','Compression'], answer:1, exp:'Digital signatures: integrity (not changed), authentication (who signed), non-repudiation (cannot deny).' },
      { q:'Crypto shredding:', opts:['Physical hard drive destruction','Overwrites data with zeros','Destroys encryption key making data unreadable','Magnetic degaussing'], answer:2, exp:'Destroy the key = data is permanently unreadable, even if storage media is retained.' },
      { q:'Egress monitoring watches:', opts:['Inbound traffic','Outbound traffic','Physical access','User login attempts'], answer:1, exp:'Egress = outbound. Monitors for unauthorized data leaving the network (exfiltration).' },
      { q:'Data at rest means:', opts:['Being transmitted','Being processed','Stored on disk or media','In temporary RAM'], answer:2, exp:'Data at rest = stored data on drives, databases, backups. At-transit = moving. In-use = processing.' },
      { q:'System hardening reduces:', opts:['Data confidentiality','Attack surface by removing unnecessary services','Network speed','User productivity'], answer:1, exp:'Hardening = remove unneeded services, close ports, apply secure configs = smaller attack surface.' },
      { q:'SMTP uses port:', opts:['22','25','53','80'], answer:1, exp:'SMTP = Simple Mail Transfer Protocol = port 25. Used for sending email.' },
      { q:'DNS primary function:', opts:['Assigns IP addresses','Resolves domain names to IP addresses','Encrypts traffic','Routes packets'], answer:1, exp:'DNS = "phone book of the internet." Translates google.com → 142.250.190.78.' },
      { q:'Hub vs Switch: hub sends data to:', opts:['Only the destination MAC','All ports (broadcast)','Only wireless clients','The router first'], answer:1, exp:'Hub = dumb repeater, broadcasts to ALL ports. Switch = smart, sends only to destination port.' },
      { q:'BGP hijacking targets:', opts:['Layer 1','Layer 2','Layer 3 routing tables','Layer 7 applications'], answer:2, exp:'BGP hijacking injects false routing information at Layer 3, redirecting internet traffic.' },
      { q:'Separation of Duties prevents:', opts:['System downtime','Single person committing fraud by controlling entire process','Malware infections','Data breaches'], answer:1, exp:'SoD = no single individual can initiate AND approve AND complete a critical transaction.' },
      { q:'Mantrap physical control:', opts:['Two guards at entry','Two-door airlock — only one opens at a time','Camera system','Badge reader'], answer:1, exp:'Mantrap/vestibule = double-door entry. Person enters outer door, it closes, then inner door opens. Prevents tailgating.' },
      { q:'Need-to-Know principle:', opts:['If cleared, access all data at that level','Access only what specific job duties require','Minimum system privileges','Zero Trust variant'], answer:1, exp:'Even with appropriate clearance, access is restricted to only what the specific job requires.' },
      { q:'ISC2 Code of Ethics: 2nd priority canon?', opts:['Advance the profession','Protect society','Act honorably, honestly, justly','Provide diligent service'], answer:2, exp:'Canon 2 = Act honorably, honestly, justly, responsibly, and legally.' },
      { q:'RBAC grants access based on:', opts:['Data sensitivity labels','Resource owner decision','Assigned job role','Multiple attributes'], answer:2, exp:'RBAC = Role-Based. Access is determined by the role assigned to the user (e.g., Doctor, Nurse, Admin).' },
      { q:'Asymmetric encryption is slower than symmetric because:', opts:['It uses shorter keys','It uses complex mathematical operations on large numbers','It requires less CPU','It has no key exchange'], answer:1, exp:'Asymmetric uses computationally expensive math (prime factoring, elliptic curves). 10-1000× slower than AES.' },
      { q:'Which BEST describes the shared responsibility model?', opts:['Cloud provider secures everything','Customer secures everything','Provider secures infrastructure; customer secures data and access','Neither party is responsible'], answer:2, exp:'Shared responsibility: provider = cloud infrastructure. Customer = data, access, applications.' },
      { q:'A WAF protects against:', opts:['Physical theft','SQL injection and XSS at Layer 7','ARP poisoning','Cable tapping'], answer:1, exp:'WAF = Web Application Firewall. Inspects HTTP traffic for Layer 7 attacks like SQLi, XSS, CSRF.' },
      { q:'Privilege creep is mitigated by:', opts:['Longer passwords','Regular access reviews and recertification','More firewalls','Faster networks'], answer:1, exp:'Periodic access reviews catch accumulated permissions from past roles that should have been revoked.' },
      { q:'Forward secrecy in TLS protects:', opts:['Future messages only','Past recorded sessions from decryption if long-term keys are later compromised','Against DDoS','Physical security'], answer:1, exp:'Forward secrecy = unique ephemeral session keys. Compromising the server key cannot decrypt past traffic.' },
      { q:'A salt added to passwords before hashing prevents:', opts:['Brute force attacks','Rainbow table attacks','DDoS attacks','Physical theft'], answer:1, exp:'Salt = random data added per password. Same password + different salt = different hash. Defeats precomputed tables.' },
      { q:'DLP systems monitor:', opts:['Physical doors','Data movement to prevent unauthorized exfiltration','CPU temperature','Login attempts only'], answer:1, exp:'DLP = Data Loss Prevention. Watches email, USB, cloud uploads for sensitive data leaving the org.' },
      { q:'Configuration management ensures:', opts:['No changes ever','Systems maintain approved documented configurations','All users have admin access','Backups run daily'], answer:1, exp:'Config management maintains consistent, documented, approved settings and detects unauthorized changes.' },
      { q:'Which hash algorithm is currently recommended?', opts:['MD5','SHA-1','SHA-256','DES'], answer:2, exp:'SHA-256 is the current standard. MD5 and SHA-1 are broken/deprecated. DES is encryption, not hashing.' },
      { q:'Tokenization differs from encryption because tokenization:', opts:['Uses mathematical algorithms','Replaces data with random tokens that have no mathematical relationship to original','Is reversible with a key','Produces fixed-length output'], answer:1, exp:'Tokens are random placeholders with no mathematical link to original data. Encryption is mathematically reversible with a key.' },
      { q:'IOC stands for:', opts:['Internet of Computers','Indicator of Compromise','Internal Operations Center','Integrated Output Control'], answer:1, exp:'IOC = Indicator of Compromise. Evidence that a breach may have occurred (malicious IPs, file hashes, etc.).' },
      { q:'A honeypot serves which purpose?', opts:['Production data storage','Attracting and studying attackers using a decoy system','Encrypting traffic','Backing up data'], answer:1, exp:'Honeypot = fake system that appears valuable to attract attackers, allowing study of their techniques.' },
      { q:'NAC checks devices for:', opts:['Physical damage','Health and compliance before granting network access','Email content','User passwords'], answer:1, exp:'NAC = Network Access Control. Verifies patch level, AV status, and compliance before network admission.' },
      { q:'Account lockout policies are which type of control?', opts:['Physical','Administrative','Technical preventive','Detective'], answer:2, exp:'Account lockout is a technical (automated) preventive control — blocks brute force login attempts.' },
      { q:'Steganography hides data:', opts:['Using encryption algorithms','Inside other files like images or audio','In hardware','In network cables'], answer:1, exp:'Steganography embeds secret data within innocent-looking files. The presence of the hidden data is itself concealed.' },
      { q:'MTBF is important because higher MTBF means:', opts:['Faster repair time','Greater system reliability','More frequent failures','Higher cost'], answer:1, exp:'MTBF = Mean Time Between Failures. Higher number = longer between failures = more reliable.' },
      { q:'An organization uses WEP encryption on its wireless network. The security team should:', opts:['Continue using WEP','Upgrade to at least WPA2 or WPA3 immediately','Add a second WEP layer','Switch to Telnet'], answer:1, exp:'WEP is completely broken — crackable in minutes. Must upgrade to WPA2 or WPA3 immediately.' },
      { q:'Split tunneling VPN risk:', opts:['All traffic is encrypted','Internet traffic bypasses corporate security controls','VPN is too slow','VPN costs more'], answer:1, exp:'Split tunnel = only corporate traffic goes through VPN. Internet traffic goes directly — bypassing security monitoring.' },
      { q:'Phishing is primarily a:', opts:['Technical attack','Social engineering attack','Physical attack','Network attack'], answer:1, exp:'Phishing exploits human trust — tricking users into clicking links or providing credentials. Social engineering.' },
      { q:'DNS poisoning redirects users to:', opts:['The correct website','A fake malicious website by corrupting DNS cache','A VPN','A backup server'], answer:1, exp:'DNS poisoning inserts fake DNS records so victims are sent to attacker-controlled sites instead of legitimate ones.' },
      { q:'Degaussing works on:', opts:['SSDs','Magnetic media only (HDDs, tapes)','Optical discs','USB flash drives'], answer:1, exp:'Degaussing uses magnetic fields — only works on magnetic storage. SSDs use flash memory and are unaffected.' },
      { q:'802.1X provides:', opts:['Wireless encryption','Port-based network access control with RADIUS authentication','IP addressing','DNS resolution'], answer:1, exp:'802.1X = port-based NAC. Device must authenticate via RADIUS before the switch/AP grants network access.' },
      { q:'Data minimization principle requires:', opts:['Collecting maximum data','Collecting only what is necessary and retaining only as long as needed','Never deleting data','Encrypting all data'], answer:1, exp:'Data minimization (GDPR, privacy best practice) = collect minimum needed, delete when no longer required.' },
      { q:'A BIA determines:', opts:['IT budget','Critical business functions and their recovery priorities','Employee salaries','Office layout'], answer:1, exp:'BIA = Business Impact Analysis. Identifies critical functions, dependencies, and sets RTO/RPO priorities.' },
      { q:'Certificate Revocation List (CRL) contains:', opts:['Active certificates','Certificates that have been revoked before their expiry date','Encryption keys','User passwords'], answer:1, exp:'CRL = list of certificates the CA has revoked (compromised key, employee left, etc.). Checked during validation.' },
      { q:'OCSP provides:', opts:['Encryption','Real-time check of whether a specific certificate is still valid','DNS resolution','Access control'], answer:1, exp:'OCSP = Online Certificate Status Protocol. Faster than downloading full CRL — queries one certificate at a time.' },
      { q:'Vulnerability scanning is:', opts:['Manual exploitation of weaknesses','Automated identification of known vulnerabilities without exploitation','Physical security review','Social engineering test'], answer:1, exp:'Scanning = automated tools check for known vulns (CVEs). No exploitation. Pen testing = manual exploitation to prove impact.' },
      { q:'Change management process ensures:', opts:['All changes are blocked','Changes are reviewed, tested, approved, and documented before implementation','Only executives can make changes','No documentation is needed'], answer:1, exp:'Change management = formal process to prevent unauthorized or untested changes from causing outages or security issues.' },
      { q:'SOC analysts primarily:', opts:['Write code','Monitor security events, investigate alerts, and respond to incidents','Manage HR','Design networks'], answer:1, exp:'SOC = Security Operations Center. Analysts monitor SIEM, investigate alerts, and coordinate incident response 24/7.' },
      { q:'Encryption at rest protects against:', opts:['Network sniffing','Physical theft of storage media','DDoS attacks','Social engineering'], answer:1, exp:'If a laptop or drive is stolen, encryption at rest makes the data unreadable without the decryption key.' },
      { q:'Which cloud model gives customers the MOST control?', opts:['SaaS','PaaS','IaaS','FaaS'], answer:2, exp:'IaaS = customer controls OS, apps, data, runtime. Most control but most responsibility. SaaS = least control.' },
      { q:'Implicit deny means:', opts:['All traffic is allowed by default','All traffic is blocked unless explicitly permitted by a rule','Only admin traffic is blocked','No rules are needed'], answer:1, exp:'Implicit deny = default action is DENY. Only traffic matching an explicit ALLOW rule passes through.' },
      { q:'Regression testing after patching verifies:', opts:['The patch was downloaded','The patch did not break existing functionality','New features were added','Users were notified'], answer:1, exp:'Regression testing = ensure the patch fixes the vulnerability without introducing new bugs or breaking existing features.' },
      { q:'A security audit differs from a vulnerability assessment because an audit:', opts:['Only uses automated tools','Evaluates compliance with policies, standards, and regulations','Only checks technical vulnerabilities','Is always external'], answer:1, exp:'Audit = formal evaluation of compliance with requirements. Assessment = identifies technical vulnerabilities.' },
      { q:'Whaling targets:', opts:['All employees','Senior executives and high-profile individuals','IT staff only','Physical infrastructure'], answer:1, exp:'Whaling = spear phishing targeting C-suite executives. Higher stakes, more sophisticated, more personalized attacks.' },
      { q:'Spear phishing differs from phishing because spear phishing is:', opts:['Less dangerous','Targeted at specific individuals with personalized content','Random mass emails','Only sent via text message'], answer:1, exp:'Spear phishing = targeted at specific person using personal information. Regular phishing = mass, generic emails.' },
      { q:'A security baseline establishes:', opts:['Maximum possible security','Minimum acceptable security configuration for systems','Optional guidelines','Emergency procedures'], answer:1, exp:'Baseline = minimum required security configuration. All systems must meet or exceed it. CIS Benchmarks are common baselines.' },
      { q:'Pretexting is a social engineering technique where the attacker:', opts:['Sends malware via email','Creates a fabricated scenario to gain trust and extract information','Breaks physical locks','Floods the network'], answer:1, exp:'Pretexting = attacker invents a convincing scenario (e.g., posing as IT support) to manipulate the victim into revealing info.' },
      { q:'The MOST important element of security awareness training is:', opts:['Length of training','Changing employee behavior toward security','Number of slides','Technical complexity'], answer:1, exp:'The goal is behavior change — employees recognizing and reporting threats. Not just knowledge transfer.' },
      { q:'Vishing is:', opts:['Video phishing','Voice phishing via phone calls','Virtual machine attack','VPN attack'], answer:1, exp:'Vishing = voice phishing. Attacker calls pretending to be a bank, IT support, etc. to extract credentials or money.' },
      { q:'Clean desk policy requires:', opts:['Cleaning the office daily','No sensitive documents visible on desks when unattended','Only digital documents','No personal items'], answer:1, exp:'Clean desk = lock screens, clear papers, secure sensitive documents when leaving the workspace. Prevents shoulder surfing and theft.' },
      { q:'Which is the correct order of the ISC2 Code of Ethics canons?', opts:['Advance, Act, Provide, Protect','Protect, Act, Provide, Advance','Act, Protect, Advance, Provide','Provide, Protect, Act, Advance'], answer:1, exp:'PAPA: Protect society → Act honorably → Provide competent service → Advance the profession. Priority order.' },
      { q:'Shoulder surfing is:', opts:['A network attack','Observing someone entering sensitive information by looking over their shoulder','A type of malware','A firewall bypass'], answer:1, exp:'Shoulder surfing = visual eavesdropping. Watching someone type passwords, PINs, or read sensitive data.' },
      { q:'A tabletop exercise is valuable because it:', opts:['Tests live systems under load','Identifies gaps in incident response plans through discussion','Replaces all other testing','Is the cheapest backup method'], answer:1, exp:'Tabletop = discussion-based IR simulation. No live systems affected. Reveals process gaps and team coordination issues.' },
      { q:'Dumpster diving is:', opts:['A network reconnaissance technique','Searching through discarded materials for sensitive information','A type of DDoS','A social media attack'], answer:1, exp:'Dumpster diving = going through trash for documents, printouts, or media containing sensitive data. Shred everything.' },
      { q:'The principle of due diligence means:', opts:['Doing the minimum required','Researching and understanding risks before making decisions','Ignoring minor risks','Delegating all security tasks'], answer:1, exp:'Due diligence = reasonable investigation and research before action. Due care = implementing appropriate protections based on that knowledge.' },
      { q:'Which attack uses a USB drive left in a parking lot?', opts:['Phishing','Baiting','Vishing','Tailgating'], answer:1, exp:'Baiting = leaving an infected USB or device where victims will find and use it. Exploits human curiosity.' },
      { q:'Smishing is:', opts:['Phishing via SMS/text messages','A network scanning tool','A type of encryption','A firewall configuration'], answer:0, exp:'Smishing = SMS phishing. Attacker sends fraudulent text messages with malicious links or urgent requests.' },
      { q:'Due care differs from due diligence because due care means:', opts:['Researching risks','Taking reasonable steps to protect assets based on known risks','Ignoring low risks','Delegating responsibility'], answer:1, exp:'Due diligence = knowing the risks. Due care = acting on that knowledge by implementing appropriate protections.' },
    ]
  }
};

export default quizzes;
